window.__denzingerWorks["dz_051"] = {"id":"dz_051","a":"Denzinger (1819-1883) — 11e éd., Bannwart S.J., 1911","t":"S. ZACHARIAS 741—752","u":"https://archive.org/details/enchiridionsymbo01denz","c":[{"t":"S. ZACHARIAS 741—752","s":[{"t":"S. ZACHARIAS 741—752","p":["De forma et ministro baptismi^."]},{"t":"ep. (10 resp. 11) «Sacris liminibus» ad Bonifacium Archiep","p":["297 . . . Quicunque sine invocatione Trinitatis lotus fuisset,857 sacramentum regenerationis non haberet . . . ; perfectus","1 Msi XII 67 B; Hrd III 1792 B; cf. Hfl III 350; rBar{Th) ad 693 n. 1 sqq (12, 135 sq)]. ^ ^","« Msi XII 339 Dsq; Jf 2286 c. Add.; Hrd III 1910 C; ML89, 943Dsq.","non est, nisi fuerit in nomine Patris et Filii et Spiritus Sancti baptizatus . . . ; si evangelicis quis verbis, invocata Trinitate, iuxta regulam a Domino positam . . . mersus esset . . ., sacramentum sine dubio haberet: et ita fortiter verbis evangelicis fuisset consecratum baptisma: ut, quamvis sceleratissimus quisque haereticus vel schismaticus, aut latro, aut fur, sive adulter, hoc homini petenti ministraret, tamen Christi esset baptisma verbis evangelicis consecratum: et e contra, licet minister iustus fuerit, si Trinitatem iuxta regulam a Domino positam in lavacro non dixisset, verum baptisma non esset, quod dedit.","(STEPHANUS II 752.) S. PAULUS I 757—767.","S. STEFHANUS III 752—757. STEPHANUS IV 768—772."]}]}]};
